// Returns the earliest time of impact [0, 1] between the ball moving from
// (x1, y1) to (x2, y2) and the brick.
function getSweepCollisionPoint(ball, brick, x1, y1, x2, y2) {
  const bMinX = brick.x - ball.r;
  const bMaxX = brick.x + brick.w + ball.r;
  const bMinY = brick.y - ball.r;
  const bMaxY = brick.y + brick.h + ball.r;

  const dx = x2 - x1;
  const dy = y2 - y1;

  let tMin = -Infinity;
  let tMax = Infinity;

  if (Math.abs(dx) < 1e-6) {
    if (x1 < bMinX || x1 > bMaxX) return null;
  } else {
    const tx1 = (bMinX - x1) / dx;
    const tx2 = (bMaxX - x1) / dx;
    tMin = Math.max(tMin, Math.min(tx1, tx2));
    tMax = Math.min(tMax, Math.max(tx1, tx2));
  }

  if (Math.abs(dy) < 1e-6) {
    if (y1 < bMinY || y1 > bMaxY) return null;
  } else {
    const ty1 = (bMinY - y1) / dy;
    const ty2 = (bMaxY - y1) / dy;
    tMin = Math.max(tMin, Math.min(ty1, ty2));
    tMax = Math.min(tMax, Math.max(ty1, ty2));
  }

  if (tMax >= tMin && tMax >= 0 && tMin <= 1) {
    const t = Math.max(0, tMin);

    // Only count collisions where the ball is moving TOWARDS the brick.
    // This prevents double-bouncing from the same face in the same frame.
    const hitX = (tMin === tMax || Math.abs(tMin - tMax) < 1e-6) || (tMin < 0 && tMax > 0);
    // This is getting complex. Let's just use a simpler check:
    // if t=0, the ball is already overlapping. Only resolve if moving towards.
    if (t === 0) {
      const ballCenterX = (x1 + x2) / 2;
      const ballCenterY = (y1 + y2) / 2;

      // Check if moving towards the brick
      const movingTowardsX = (ballCenterX < brick.x + brick.w / 2) ? dx > 0 : dx < 0;
      const movingTowardsY = (ballCenterY < brick.y + brick.h / 2) ? dy > 0 : dy < 0;

      // If not moving towards either axis, ignore.
      // But this is too simple.
    }

    return t;
  }
  return null;
}

